def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'C'
    if n >= 3:
        opp = [history[i][1] for i in range(n)]
        mine = [history[i][0] for i in range(n)]
        # Detect always defect
        if all(x == 'D' for x in opp):
            return 'D'
        # Detect always cooperate
        if all(x == 'C' for x in opp):
            return 'C'
        # Detect tit-for-tat-like: defect if previous opponent defected
        if n >= 5:
            tft_match = 0
            for i in range(1, n):
                if opp[i-1] == 'D':
                    if opp[i] == 'D':
                        tft_match += 1
                else:
                    if opp[i] == 'C':
                        tft_match += 1
            if tft_match >= n - 2:
                # Mirror opponent's last move
                return opp[-1]
        # Detect alternator
        if n >= 6:
            alt = 0
            for i in range(2, n):
                if opp[i] != opp[i-2]:
                    alt += 1
            if alt >= n - 3:
                # Predict next move as opposite of last
                return 'D' if opp[-1] == 'C' else 'C'
        # Count defections
        dc = opp.count('D')
        cc = opp.count('C')
        # If opponent mostly cooperates, cooperate
        if dc == 0:
            return 'C'
        if dc * 3 < n:
            return 'C'
        # If opponent mostly defects, defect
        if dc * 2 > n:
            return 'D'
        # Look at last few rounds
        recent = opp[-5:]
        rdc = recent.count('D')
        rcc = recent.count('C')
        if rdc >= 4:
            return 'D'
        if rdc == 0:
            return 'C'
        # Mixed: mirror last opponent move with forgiveness
        if opp[-1] == 'D':
            # Forgive occasionally
            if n > 10 and opp[-2] == 'C':
                return 'C'
            return 'D'
        return 'C'
    return 'C'
